// Title: Export a workbook containing WordArt to HTML and embed a W3C‑valid CSS linear gradient with Aspose.Cells in C#
// Common Searches: Aspose.Cells C# export worksheet that includes WordArt to HTML | how to add a custom CSS linear‑gradient background to HTML generated by Aspose.Cells | inject CSS styles into Aspose.Cells HTML output using C# | use C# regex to confirm linear‑gradient syntax in saved HTML file | validate that modified HTML from Aspose.Cells is well‑formed XML in C#
// Tags: Aspose.Cells export WordArt shape as HTML | C# insert custom CSS gradient into generated HTML | regex check for linear‑gradient syntax in HTML | XDocument parse HTML for well‑formedness in C# | HtmlSaveOptions ExportActiveWorksheetOnly setting

using System;
using System.IO;
using System.Text.RegularExpressions;
using Aspose.Cells;
using Aspose.Cells.Drawing;
using System.Xml.Linq;

// The sample creates a workbook, adds a WordArt shape, and saves the active worksheet as HTML using Aspose.Cells. It then reads the HTML file, injects a W3C‑compliant linear‑gradient CSS block before the closing </head> tag, and writes the updated content back. A regular expression validates the presence of the gradient syntax, and XDocument parsing confirms the HTML remains well‑formed XML.
class Program
{
    static void Main()
    {
        // Path to the output HTML file
        const string htmlFilePath = "WordArt.html";

        // -----------------------------------------------------------------
        // 1. Create a workbook and add a WordArt shape
        // -----------------------------------------------------------------
        try
        {
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];

            // Add a WordArt shape (preset style, text, position and size)
            // Parameters: style, text, topRow, top, leftColumn, left, height, width
            Shape wordArt = sheet.Shapes.AddWordArt(
                PresetWordArtStyle.WordArtStyle1,
                "Aspose Cells WordArt",
                2,          // topRow
                20,         // top (pixels)
                2,          // leftColumn
                20,         // left (pixels)
                100,        // height (pixels)
                400);       // width (pixels)

            // Optionally, set some formatting on the WordArt
            wordArt.TextEffect.FontSize = 24;
            wordArt.TextEffect.FontBold = true;

            // -----------------------------------------------------------------
            // 2. Save the workbook as HTML
            // -----------------------------------------------------------------
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html)
            {
                // Export only the active worksheet to keep the output small
                ExportActiveWorksheetOnly = true
            };

            workbook.Save(htmlFilePath, htmlOptions);
            Console.WriteLine($"Workbook saved as HTML to '{htmlFilePath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during workbook creation or saving: {ex.Message}");
            return;
        }

        // -----------------------------------------------------------------
        // 3. Inject a W3C‑valid CSS gradient into the generated HTML
        // -----------------------------------------------------------------
        try
        {
            if (!File.Exists(htmlFilePath))
            {
                Console.WriteLine($"HTML file '{htmlFilePath}' was not found.");
                return;
            }

            string htmlContent = File.ReadAllText(htmlFilePath);

            // Define a simple linear gradient that is valid according to W3C CSS specifications
            const string gradientCss = @"
<style>
/* W3C‑valid linear gradient for the page background */
body {
    background: linear-gradient(to right, #ff7e5f, #feb47b);
    margin: 0;
    padding: 0;
}
</style>
";

            // Insert the CSS just before the closing </head> tag
            int headCloseIndex = htmlContent.IndexOf("</head>", StringComparison.OrdinalIgnoreCase);
            if (headCloseIndex >= 0)
            {
                htmlContent = htmlContent.Insert(headCloseIndex, gradientCss);
            }
            else
            {
                // Fallback: prepend to the file if </head> is missing
                htmlContent = gradientCss + htmlContent;
            }

            File.WriteAllText(htmlFilePath, htmlContent);
            Console.WriteLine("Injected W3C‑valid CSS gradient into the HTML file.");

            // -----------------------------------------------------------------
            // 4. Perform a lightweight validation that the gradient syntax is present
            // -----------------------------------------------------------------
            bool gradientFound = Regex.IsMatch(
                htmlContent,
                @"linear-gradient\(\s*to\s+right\s*,\s*#[0-9a-fA-F]{6}\s*,\s*#[0-9a-fA-F]{6}\s*\)",
                RegexOptions.IgnoreCase);

            Console.WriteLine(gradientFound
                ? "Validation passed: CSS gradient syntax detected."
                : "Validation failed: CSS gradient syntax not found.");

            // -----------------------------------------------------------------
            // 5. (Optional) Verify that the resulting HTML is well‑formed XML
            // -----------------------------------------------------------------
            try
            {
                XDocument.Parse(htmlContent);
                Console.WriteLine("HTML well‑formedness check passed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"HTML well‑formedness check failed: {ex.Message}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during HTML processing: {ex.Message}");
        }

        Console.WriteLine("Processing complete.");
    }
}
